// SINGLE AGENT - WebContainer Mode (Like Lovable)
// Returns file operations as JSON for frontend to apply

const ctx = $input.item.json;
const OPENROUTER_KEY = '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';
const MODEL = 'google/gemini-3-flash-preview';

console.log('🚀 WebContainer AI processing:', ctx.message);

const TOOLS = [
  {
    type: 'function',
    function: {
      name: 'write_file',
      description: 'Create or overwrite a file with content. Use this for creating new files or completely rewriting existing ones.',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'File path (e.g., src/app/page.tsx)' },
          content: { type: 'string', description: 'Complete file content' }
        },
        required: ['path', 'content']
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'str_replace',
      description: 'Replace specific text in a file. Use for small edits to existing files.',
      parameters: {
        type: 'object',
        properties: {
          file: { type: 'string', description: 'File path' },
          old_text: { type: 'string', description: 'Exact text to find and replace' },
          new_text: { type: 'string', description: 'New text to insert' }
        },
        required: ['file', 'old_text', 'new_text']
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'delete_file',
      description: 'Delete a file',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'File path to delete' }
        },
        required: ['path']
      }
    }
  }
];

const SYSTEM = `You are an expert Next.js/TypeScript developer. You help users build beautiful web applications.

Rules:
1. Use write_file for new files or complete rewrites
2. Use str_replace for small edits to existing files
3. Create modern, beautiful UIs with Tailwind CSS
4. Use TypeScript with proper types
5. After making changes, provide a brief summary of what you did

The user's project runs in a WebContainer. Changes are applied instantly.
Existing files: ${(ctx.existingFiles || []).slice(0, 20).join(', ') || 'None yet - new project'}`;

const userMessage = ctx.message;
let messages = [{ role: 'user', content: userMessage }];
let operations = [];
let thinkingSteps = [];
let stepNum = 1;

// Simulate file operations (collect them for frontend to apply)
const executeToolCall = (name, args) => {
  if (name === 'write_file') {
    operations.push({ type: 'write', path: args.path, content: args.content });
    thinkingSteps.push({ step: stepNum++, message: 'Creating: ' + args.path, status: 'complete' });
    return JSON.stringify({ success: true, path: args.path });
  }
  if (name === 'str_replace') {
    operations.push({ type: 'modify', path: args.file, oldText: args.old_text, newText: args.new_text });
    thinkingSteps.push({ step: stepNum++, message: 'Modifying: ' + args.file, status: 'complete' });
    return JSON.stringify({ success: true, path: args.file });
  }
  if (name === 'delete_file') {
    operations.push({ type: 'delete', path: args.path });
    thinkingSteps.push({ step: stepNum++, message: 'Deleting: ' + args.path, status: 'complete' });
    return JSON.stringify({ success: true, path: args.path });
  }
  return JSON.stringify({ error: 'Unknown tool' });
};

let output = '';
let iterations = 0;
const MAX_ITERATIONS = 10;

try {
  for (let i = 0; i < MAX_ITERATIONS; i++) {
    iterations++;
    thinkingSteps.push({ step: stepNum++, message: 'Thinking...', status: 'running' });

    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: {
        'Authorization': 'Bearer ' + OPENROUTER_KEY,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'https://n8n.io'
      },
      body: JSON.stringify({
        model: MODEL,
        messages: [{ role: 'system', content: SYSTEM }, ...messages],
        tools: TOOLS,
        temperature: 0.3
      }),
      timeout: 90000,
      json: true
    });

    const choice = response.choices?.[0];
    const message = choice?.message;

    if (!message) {
      output = 'No response from AI';
      break;
    }

    messages.push(message);

    // Handle tool calls
    if (message.tool_calls && message.tool_calls.length > 0) {
      for (const tc of message.tool_calls) {
        let args = {};
        try { args = JSON.parse(tc.function.arguments); } catch (e) {}
        const result = executeToolCall(tc.function.name, args);
        messages.push({
          role: 'tool',
          tool_call_id: tc.id,
          content: result
        });
      }
    } else {
      // No tool calls = final response
      output = message.content || 'Done';
      thinkingSteps[thinkingSteps.length - 1].status = 'complete';
      thinkingSteps[thinkingSteps.length - 1].message = 'Complete';
      break;
    }
  }
} catch (e) {
  output = 'Error: ' + e.message;
  thinkingSteps.push({ step: stepNum++, message: 'Error: ' + e.message, status: 'error' });
}

console.log('✅ Completed with', operations.length, 'file operations');

return [{
  json: {
    success: true,
    summary: output,
    operations,
    thinkingSteps,
    iterations,
    filesCreated: operations.filter(o => o.type === 'write').map(o => o.path),
    filesModified: operations.filter(o => o.type === 'modify').map(o => o.path),
    filesDeleted: operations.filter(o => o.type === 'delete').map(o => o.path)
  }
}];
